# Post-policy sustainability: average adoption rate after mandate end for 30 days
mend = int(self.params.get("policy_mandate_end_day", 45))
post_window = list(range(mend + 1, min(mend + 31, len(sim_adopt))))
if post_window:
    vals = [sim_adopt[i] for i in post_window if i < len(sim_adopt)]
    metrics["post_policy_sustainability"] = sum(vals) / max(1, len(vals))
else:
    metrics["post_policy_sustainability"] = None
# Average compliance by location type
avg_comp = {"home": None, "work": None, "public": None}
if sim_compliance_hist:
    sums = {"home": 0.0, "work": 0.0, "public": 0.0}
    cnt = 0
    for d in sim_compliance_hist:
        for k in ["home", "work", "public"]:
            if d.get(k) is not None:
                sums[k] += float(d.get(k))
        cnt += 1
    if cnt > 0:
        avg_comp = {k: (sums[k] / cnt) for k in sums}
metrics["average_compliance_by_location_type"] = avg_comp
# Compliance under mandate (average adoption rate during mandate days)
start_day = int(self.params.get("policy_mandate_start_day", 20))
end_day = int(self.params.get("policy_mandate_end_day", 45))
if sim_adopt and end_day < len(sim_adopt):
    active_days = sim_adopt[start_day:end_day + 1] if start_day < len(sim_adopt) else []
    metrics["compliance_under_mandate"] = (sum(active_days) / len(active_days)) if active_days else None
else:
    metrics["compliance_under_mandate"] = None
# Exposure to misinformation (average)
mis_hist = self.state.get("misinformation_rate_history", [])
metrics["exposure_to_misinformation"] = (sum(mis_hist) / len(mis_hist)) if mis_hist else None
# Group adoption disparity (naming alignment)
metrics["group_adoption_disparity"] = metrics.get("inequality_index_by_group")
# Metrics vs ground truth
metrics["RMSE_adoption_rate"] = rmse(sim_adopt, gt_adopt) if gt_adopt else float("nan")
metrics["MAE_cumulative_adopters"] = float("nan")  # set to NaN unless a proper time series is implemented
metrics["PearsonR_adoption_rate"] = pearsonr(sim_adopt, gt_adopt) if gt_adopt else float("nan")
